from __future__ import absolute_import
import os
from selenium.webdriver.common.by import By
from taf.selenium.sbts.common.debug import Debug
from taf.selenium.sbts.common.common import LocalBasicPage
from taf.selenium.sbts.pages.modals import (LegalNoticeModal,
                                            WebElementManagerReloadModal,
                                            BtsStartUpViewModal,
                                            SessionEstablishmentError,
                                            AdditionalHardwareDetectedModal,
                                            DowngradedPrivilegesModal)
from taf.selenium.sbts.common.exceptions import FileExistsException, FileNotFoundException


class LoginPage(LocalBasicPage):
    def __init__(self, webdriver):
        super(LoginPage, self).__init__(webdriver)

    def _insert_username(self, locator, username, timeout=60):
        self.insert_text_to_enable_element(locator, username, timeout)

    def _insert_password(self, locator, password, timeout=60):
        self.insert_text_to_enable_element(locator, password, timeout)

    def _click_login_button(self, locator, timeout=60):
        self.click_enabled_element(locator, timeout)


class SbtsLoginPage(LoginPage):
    """
    A class manages login page, login function included.
    """
    _INPUT_USERNAME_XPATH = '//input[@name="username" or @placeholder="Username"]'
    _INPUT_PASSWORD_XPATH = '//input[@name="password" or @placeholder="Password"]'
    _OPTIONS_BUTTON_XPATH = '//*[@*="Options"]'
    _SSL_LABEL_XPATH = '//*[text()="SSL"]'
    _SSL_CHECKBOX_XPATH = '//input[@*="useSSL" or @id="SSL"]'
    _READONLY_CHECKBOX_NOT_SELECTED_XPATH = '//input[@aria-checked="false" and @id="readOnly"]'
    _READONLY_CHECKBOX_SELECTED_XPATH = '//input[@aria-checked="true" and @id="readOnly"]'
    _PORT_LABEL_XPATH = '//*[text()="Port"]'
    _PORT_INPUT_XPATH = '//*[text()="Port"]//following-sibling::input'

    _LOGIN_BUTTON_XPATH = '//*[@*="Login"]'
    SESSION_LOCKED_XPATH = '//*[text()="Session locked"]'
    PASSWD_INPUT_XPATH = '//input[@id="screen-lock-password-input"]'
    LOGO_XPATH = '//*[@class="logo" and @name="Nokia"]'

    def __init__(self, webdriver, screenshot_dir):
        super(SbtsLoginPage, self).__init__(webdriver)
        self._screenshot_dir = screenshot_dir
        self._legal_notice_modal = LegalNoticeModal(webdriver)
        self._reload_modal = WebElementManagerReloadModal(webdriver)
        self._bts_start_up_view_modal = BtsStartUpViewModal(webdriver)
        self._session_estab_error_modal = SessionEstablishmentError(webdriver)
        self._additional_hardware_detected_modal = AdditionalHardwareDetectedModal(webdriver)
        self._downgraded_privileges_modal = DowngradedPrivilegesModal(webdriver)

    def _click_additional_hardware_detected_modal(self, timeout, button):
        if self._additional_hardware_detected_modal.wait_for_additional_hardware_detected_modal_appear(timeout):
            if button.lower() == "start sync":
                self._additional_hardware_detected_modal.start_sync(timeout)
            self._additional_hardware_detected_modal.close(timeout)

    def _click_modals(self, modal_action_configurations):
        modal_action_configurations = modal_action_configurations or []

        for _, config in enumerate(modal_action_configurations):
            modal_name = config['modal_name'].strip().lower()
            if modal_name == "additional hardware detected":
                self._click_additional_hardware_detected_modal(timeout=int(config.get("timeout", 20)),
                                                               button=config.get("button", "close"))

    def _configure_port_and_ssl(self, port, ssl):
        self.click_and_wait_for_corresponding_element_visible(self._OPTIONS_BUTTON_XPATH,
                                                              self._PORT_LABEL_XPATH)
        self.select_checkbox_by_specified_status(ssl, self._SSL_CHECKBOX_XPATH, self._SSL_CHECKBOX_XPATH)
        self.insert_text_to_enable_element((By.XPATH, self._PORT_INPUT_XPATH), port)

    def _configure_readonly_option(self, readonly):
        if readonly and self.element_exists((By.XPATH, self._READONLY_CHECKBOX_NOT_SELECTED_XPATH), timeout=1):
            elem = self.driver.find_element(By.XPATH, self._READONLY_CHECKBOX_NOT_SELECTED_XPATH)
            self.driver.execute_script("arguments[0].click();", elem)

        if not readonly and self.element_exists((By.XPATH, self._READONLY_CHECKBOX_SELECTED_XPATH), timeout=1):
            elem = self.driver.find_element(By.XPATH, self._READONLY_CHECKBOX_SELECTED_XPATH)
            self.driver.execute_script("arguments[0].click();", elem)

    def login(self, url, username, password, wait_session_modal_timeout=10, port=443, ssl=True,
              timeout=60, modal_action_configurations=None, readonly=False):
        try:
            self.driver.get(url)
            self._insert_username((By.XPATH, self._INPUT_USERNAME_XPATH), username, timeout)
            self._insert_password((By.XPATH, self._INPUT_PASSWORD_XPATH), password, timeout)
            self._configure_port_and_ssl(port, ssl)
            self._configure_readonly_option(readonly)
            self._click_login_button((By.XPATH, self._LOGIN_BUTTON_XPATH), timeout)

            if self._session_estab_error_modal.wait_until_session_estab_error_modal_appear(wait_session_modal_timeout):
                return self._session_estab_error_modal.get_session_estab_error()

            self._click_modals(modal_action_configurations)

            if self._bts_start_up_view_modal.wait_for_start_up_view_modal_appear():
                self._bts_start_up_view_modal.close()

            self._legal_notice_modal.wait_until_legal_notice_modal_appear(timeout)
            self._legal_notice_modal.confirm()

            if self._bts_start_up_view_modal.wait_for_start_up_view_modal_appear():
                self._bts_start_up_view_modal.close()

            if readonly and self._downgraded_privileges_modal.wait_until_downgraded_privileges_modal_appear(timeout=2):
                self._downgraded_privileges_modal.confirm(timeout=2)

            self._reload_modal.wait_until_login_modal_appear(timeout=2)
            self._reload_modal.confirm(timeout=2)

        except Exception:
            Debug(self.driver, self._screenshot_dir).save_screenshot('login')
            self.close_browser()
            raise

    def login_with_offline_mode(self, file_path):
        if not os.path.exists(file_path):
            raise FileExistsException('file path {file_path} is not exist.'.format(file_path=file_path))
        if not os.path.isfile(file_path):
            raise FileNotFoundException('can not find {file_path}.'.format(file_path=file_path))
        if "firefox" in self.driver.name:
            file_path = "file:\\" + file_path
        self.driver.get(file_path)

    def login_after_screen_lock(self, passwd, timeout=60):
        """
        Keyword for login into webem after screen lock.
        :param passwd: password for webem
        :type passwd: str
        :param timeout: timeout
        :type timeout: str or int
        """
        self.wait_for_visibility_by_xpath(self.SESSION_LOCKED_XPATH, timeout)
        self.insert_text_to_enable_element_and_enter((By.XPATH, self.PASSWD_INPUT_XPATH), passwd, timeout)
        self.wait_for_visibility_by_xpath(self.LOGO_XPATH, timeout)


class LabAccessLoginPage(LoginPage):
    _INPUT_USERNAME_XPATH = '//input[@id="username"]'
    _INPUT_PASSWORD_XPATH = '//input[@id="password"]'
    _SIGN_IN_XPATH = '//input[@type="submit"]'
    _LOGOUT_BUTTON_XPATH = '//td[@id="SignOutbg"]'

    def __init__(self, driver):
        super(LabAccessLoginPage, self).__init__(driver)

    def login(self, url, username, password, timeout=60):
        self.driver.get(url)
        self._insert_username((By.XPATH, self._INPUT_USERNAME_XPATH), username, timeout)
        self._insert_password((By.XPATH, self._INPUT_PASSWORD_XPATH), password, timeout)
        self._click_login_button((By.XPATH, self._SIGN_IN_XPATH), timeout)

        self.wait_for_visibility((By.XPATH, self._LOGOUT_BUTTON_XPATH), timeout)
        self.switch_to_sbts_login_tab()


class LogoutPage(LocalBasicPage):
    """
    A class manages logout page, logout function included.
    """
    _USER_COUNT_VIEW_XPATH = '//user-account-management'
    _LOGOUT_BUTTON_XPATH = '//div[@class="user-account-view"]//ui-button[@a-text="Logout"]'

    def __init__(self, driver):
        super(LogoutPage, self).__init__(driver)

    def logout(self, click_timeout, timeout=60):
        """
        Logout from selenium_sbts web.
        :param click_timeout: int, timeout to being able to click
        :param timeout: int, timeout
        """
        try:
            self.wait_until_element_is_clickable(self._USER_COUNT_VIEW_XPATH, click_timeout)
            self.click_enabled_element_after_visible((By.XPATH, self._USER_COUNT_VIEW_XPATH), timeout)

            self.wait_until_element_is_clickable(self._LOGOUT_BUTTON_XPATH, click_timeout)
            self.click_enabled_element_after_visible((By.XPATH, self._LOGOUT_BUTTON_XPATH), timeout)
        except Exception:
            raise
